import {
  accessTokenCustomClaims,
  onUserTokenGeneratedEvent,
} from "@kinde/infrastructure";

export default async function workflow(event: onUserTokenGeneratedEvent) {
  const accessToken = accessTokenCustomClaims<{ companyName: string }>();
  accessToken.companyName = "Acme Inc.";
}

const issuerUrl = "https://account.example.com";

const authUrl = `${issuerUrl}/oauth2/auth`;
console.log(authUrl);

const flags = accessToken.feature_flags ?? {};

const darkMode = flags.dark_mode?.v === true;
const checkoutVariant = flags.checkout_variant?.v ?? "control";

if (darkMode) {
  enableDarkMode();
}

renderCheckout(checkoutVariant);

const token = await getManagementApiToken();

const response = await fetch(
  "https://<your-kinde-domain>/api/v1/feature_flags",
  {
    headers: { Authorization: `Bearer ${token}` }
  }
);

if (!response.ok) throw new Error(`HTTP ${response.status}`);
const flags = await response.json();
console.log(flags);

import { useKindeAuth } from "@kinde-oss/kinde-auth-react";

export async function callApi() {
  const { getAccessToken } = useKindeAuth();
  const token = await getAccessToken();
  if (!token) return;

  const response = await fetch("https://api.example.com/data", {
    headers: { Authorization: `Bearer ${token}` },
  });
  return response.json();
}

