const orgCode = "org_123";

const response = await fetch(
  `https://${process.env.KINDE_DOMAIN}/api/v1/organization/${orgCode}`,
  {
    method: "PATCH",
    headers: {
      Authorization: `Bearer ${process.env.KINDE_ACCESS_TOKEN}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({ is_suspended: true })
  }
);

if (!response.ok) throw new Error(await response.text());

// Enable Passwordless in Kinde Dashboard:
// Settings > Environment > Authentication
// Passwordless > Email connections > Code
// Select your application, then Save.

const verifier = crypto.randomUUID();
const challenge = await crypto.subtle.digest(
  "SHA-256",
  new TextEncoder().encode(verifier),
);
const codeChallenge = btoa(String.fromCharCode(...new Uint8Array(challenge)))
  .replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");

const authorizationUrl = new URL("https://yourbusiness.kinde.com/oauth2/auth");
authorizationUrl.search = new URLSearchParams({
  client_id: "YOUR_CLIENT_ID",
  redirect_uri: "https://example.com/callback",
  response_type: "code",
  scope: "openid email offline",
  code_challenge: codeChallenge,
  code_challenge_method: "S256",
}).toString();

console.log(authorizationUrl.toString());

app.get("/register", async (req, res) => {
