import express from "express";
import jwt from "jsonwebtoken";

const app = express();
app.use(express.text({ type: "application/jwt" }));

app.post("/webhooks/kinde", (req, res) => {
  const token = req.body;
  const payload = jwt.decode(token);
  console.log(payload);
  res.sendStatus(200);
});

app.listen(3000);
